<?php
declare(strict_types=1);
header('Cache-Control: no-store, private');header('X-Content-Type-Options: nosniff');header('X-Frame-Options: DENY');header('Referrer-Policy: same-origin');
header("Content-Security-Policy: default-src 'none'; style-src 'unsafe-inline'; script-src 'unsafe-inline'; form-action 'self'; base-uri 'none'; frame-ancestors 'none'");
$crmMethod=$_SERVER['REQUEST_METHOD']??'GET';
if(!in_array($crmMethod,['GET','POST'],true)){header('Allow: GET, POST');http_response_code(405);exit;}
if(getenv('OFFICE_BASE_PATH')!=='/office-test'||getenv('OFFICE_TEST_CRM_ENABLED')!=='enabled'||getenv('OFFICE_CRM_AUTH_MODE')!=='session_only'||getenv('OFFICE_CRM_OPPORTUNITIES_SCHEMA_VERIFIED')!=='enabled'||getenv('OFFICE_CRM_OPPORTUNITIES_WORKSPACE_SCHEMA_VERIFIED')!=='enabled'){http_response_code(503);exit('Verkoopkansen zijn nog niet beschikbaar.');}
$crmHost=getenv('OFFICE_PUBLIC_HOST');
if(!is_string($crmHost)||$crmHost===''||!hash_equals($crmHost,(string)($_SERVER['HTTP_HOST']??''))||empty($_SERVER['HTTPS'])||$_SERVER['HTTPS']==='off'){http_response_code(403);exit;}
if($crmMethod==='POST'&&(!hash_equals('https://'.$crmHost,(string)($_SERVER['HTTP_ORIGIN']??''))||(int)($_SERVER['CONTENT_LENGTH']??0)>65536)){http_response_code(403);exit('Ongeldige formulierherkomst.');}
try{
    foreach(['OfficeMount.php','WebsiteCrmOperatorContext.php','WebsiteCrmOperatorSessionProviderInterface.php','WebsiteOfficeCrmSessionRepository.php','WebsiteOfficeCrmCookieSessionProvider.php'] as $f)require_once dirname(__DIR__).'/src/Intake/'.$f;
    foreach(['OfficeCrmFunnel.php','OfficeCrmOpportunityPolicy.php','OfficeCrmFunnelViews.php','OfficeCrmOpportunityRepository.php'] as $f)require_once dirname(__DIR__).'/src/Crm/'.$f;
    $crmDb=new PDO(getenv('OFFICE_INTAKE_PDO_DSN')?:'',getenv('OFFICE_INTAKE_DB_USER')?:'',getenv('OFFICE_INTAKE_DB_PASSWORD')?:'',[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_EMULATE_PREPARES=>false]);
    $crmOperator=(new \Brebo\Office\Intake\WebsiteOfficeCrmCookieSessionProvider(new \Brebo\Office\Intake\WebsiteOfficeCrmSessionRepository($crmDb),$_COOKIE,time()))->currentOperator();
    if($crmOperator===null){if($crmMethod==='POST'){http_response_code(401);exit('Sessie verlopen.');}header('Location: '.\Brebo\Office\Intake\OfficeMount::route('inloggen'),true,302);exit;}
    $crmRepo=new \Brebo\Office\Crm\OfficeCrmOpportunityRepository($crmDb);$crmRepo->authorize($crmOperator->operatorId);
    $crmCanWrite=$crmOperator->canEditCrm&&getenv('OFFICE_CRM_OPPORTUNITIES_WRITE_ENABLED')==='enabled';
    if($crmMethod==='POST')$crmRepo->authorize($crmOperator->operatorId,true);
    if($crmMethod==='POST'&&!$crmCanWrite){http_response_code(403);exit('Geen CRM-wijzigingsrechten.');}
    if(session_status()!==PHP_SESSION_ACTIVE){session_name('BREBO_CRM_OPPORTUNITY_FORM');session_set_cookie_params(['lifetime'=>0,'path'=>'/office-test','secure'=>true,'httponly'=>true,'samesite'=>'Strict']);if(!@session_start())throw new RuntimeException('form session');}
    $crmSessionScope=hash('sha256',$crmOperator->operatorId.':'.$crmOperator->sessionId);
    if(($_SESSION['crm_opportunity_scope']??null)!==$crmSessionScope||(int)($_SESSION['crm_opportunity_expiry']??0)<time()){
        $_SESSION['crm_opportunity_scope']=$crmSessionScope;$_SESSION['crm_opportunity_csrf']=bin2hex(random_bytes(32));$_SESSION['crm_opportunity_expiry']=time()+1800;
    }
    if($crmMethod==='POST'&&(!is_string($_POST['csrf']??null)||!hash_equals($_SESSION['crm_opportunity_csrf'],$_POST['csrf']))){http_response_code(403);exit('Ongeldige of verlopen formulierbeveiliging.');}
}catch(DomainException $e){http_response_code(403);exit('Geen CRM-toegang.');}catch(Throwable $e){http_response_code(503);exit('CRM tijdelijk niet beschikbaar.');}
function crmH(mixed $v):string{return htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
function crmStart(string $title):void{
    header('Content-Type: text/html; charset=utf-8');
    echo '<!doctype html><html lang="nl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'.crmH($title).' · BREBO Office</title><style>body{margin:0;font:16px system-ui;background:#f4f6fa;color:#203247}main{max-width:1400px;margin:auto;padding:28px}section{background:white;border:1px solid #dce3eb;border-radius:10px;padding:20px;margin:16px 0}a{color:#175a91}.crm-tabs,.crm-view-switch{display:flex;flex-wrap:wrap;gap:14px;margin:18px 0}.crm-fields{display:grid;grid-template-columns:repeat(auto-fit,minmax(250px,1fr));gap:14px}label{display:block;margin-top:12px}input,select,textarea{box-sizing:border-box;width:100%;padding:10px;border:1px solid #b7c5d2;border-radius:6px;font:inherit}textarea{min-height:100px}button,.crm-button{display:inline-block;padding:11px 18px;border:0;border-radius:6px;background:#175a91;color:white;font:inherit;text-decoration:none;margin-top:14px}table{border-collapse:collapse;width:100%;background:white}th,td{padding:12px;text-align:left;border-bottom:1px solid #dde4ec}.crm-calendar-grid{display:grid;grid-template-columns:repeat(7,minmax(0,1fr));gap:5px}.crm-calendar-day{min-height:100px;padding:8px;border:1px solid #dce3eb;background:white;overflow-wrap:anywhere}.crm-calendar-day article{font-size:13px}.crm-calendar-day h3{margin:0}.crm-muted{color:#586a7c}.crm-error{color:#9b2226}details{margin:12px 0}@media(max-width:760px){main{padding:16px}.crm-calendar-grid{grid-template-columns:1fr}.crm-calendar-empty{display:none}}</style></head><body><main><nav class="crm-tabs" aria-label="CRM-onderdelen"><a href="/office-test/crm/relaties">Relaties</a><a href="/office-test/marketing/leads">Marketing · Leads</a><a href="/office-test/crm/verkoopkansen">Verkoopkansen</a></nav><h1>'.crmH($title).'</h1>';
}
function crmHidden(string $name,mixed $value):void{echo '<input type="hidden" name="'.crmH($name).'" value="'.crmH($value).'">';}
function crmFormFields(array $data,array $choices,int $opportunityId=0):void{
    echo '<div class="crm-fields"><div><label for="title">Onderwerp</label><input id="title" name="title" maxlength="255" required value="'.crmH($data['title']??'').'"></div><div><label for="relation_search">Relatie zoeken</label><input id="relation_search" type="search" placeholder="Zoek op relatienaam" autocomplete="off" aria-controls="relation_id"><label for="relation_id">Relatie</label><select id="relation_id" name="relation_id" required><option value="">Kies een relatie</option>';
    foreach($choices['relations'] as $r)echo '<option value="'.(int)$r['id'].'"'.((string)($data['relation_id']??'')===(string)$r['id']?' selected':'').'>'.crmH($r['display_name']).'</option>';
    echo '</select><a class="crm-button" href="/office-test/crm/relaties/nieuw'.($opportunityId>0?'?opportunity_id='.$opportunityId:'').'" style="margin-top:8px">+ Nieuwe relatie toevoegen</a></div><div><label for="contact_id">Contactpersoon</label><select id="contact_id" name="contact_id"><option value="">Geen contactpersoon</option>';
    foreach($choices['contacts'] as $c){$name=trim($c['given_name'].' '.$c['family_name']);$relation='';foreach($choices['relations'] as $r)if((int)$r['id']===(int)$c['relation_id'])$relation=$r['display_name'];echo '<option value="'.(int)$c['id'].'"'.((string)($data['contact_id']??'')===(string)$c['id']?' selected':'').'>'.crmH($name.' · '.$relation).'</option>';}
    echo '</select></div><div><label for="service_type">Dienst</label><select id="service_type" name="service_type">';
    foreach(\Brebo\Office\Crm\OfficeCrmOpportunityPolicy::SERVICES as $key=>$label)echo '<option value="'.$key.'"'.(($data['service_type']??'execution')===$key?' selected':'').'>'.crmH($label).'</option>';
    echo '</select></div><div><label for="expected_value">Verwachte waarde excl. btw (€)</label><input id="expected_value" name="expected_value" inputmode="decimal" value="'.crmH($data['expected_value']??'').'"></div><div><label for="expected_close_date">Verwachte opdracht</label><input id="expected_close_date" type="date" name="expected_close_date" value="'.crmH($data['expected_close_date']??'').'"></div></div><label for="description">Toelichting / scope</label><textarea id="description" name="description" maxlength="12000">'.crmH($data['description']??'').'</textarea>';
    echo '<script>(function(){const search=document.getElementById("relation_search"),select=document.getElementById("relation_id"),contact=document.getElementById("contact_id");if(!search||!select)return;const options=Array.from(select.options).map(o=>({value:o.value,label:o.textContent}));const contacts=contact?Array.from(contact.options).map(o=>({value:o.value,label:o.textContent})):[];function updateContacts(){if(!contact)return;const chosen=select.options[select.selectedIndex]?.textContent||"";const previous=contact.value;contact.replaceChildren();for(const c of contacts){if(c.value&&(!chosen||!c.label.endsWith(" · "+chosen)))continue;contact.add(new Option(c.label,c.value));}if(Array.from(contact.options).some(o=>o.value===previous))contact.value=previous;}search.addEventListener("input",function(){const selected=select.value;const q=search.value.trim().toLocaleLowerCase("nl");select.replaceChildren();for(const o of options){if(o.value&&q&&!o.label.toLocaleLowerCase("nl").includes(q)&&o.value!==selected)continue;select.add(new Option(o.label,o.value));}select.value=selected;});select.addEventListener("change",updateContacts);updateContacts();})();</script>';
}
